// Checks the uploaded file and decides where in docs/ it is saved.
// Set DOCS_FOLDER to the docs folder of your project (it must match the folder the
// n8n start script allows: <project>\docs).
const DOCS_FOLDER = 'C:\\path\\to\\rag-project\\docs';
const ALLOWED = ['.pdf', '.docx', '.txt', '.md'];
const MAX_BYTES = 10 * 1024 * 1024;

const item = $input.first();
const keys = Object.keys(item.binary || {});
const reject = (error) => [{ json: { ok: false, error } }];

if (keys.length === 0) return reject('No file was received.');
const file = item.binary[keys[0]];

// keep only the file name (drop any folders), then replace odd characters
let name = String(file.fileName || '').split(/[\\/]/).pop().trim();
if (name.startsWith('~$')) return reject('That looks like a Word lock file, not a document.');
name = name.replace(/[^A-Za-z0-9 ._()\-]/g, '_').replace(/^\.+/, '');
const dot = name.lastIndexOf('.');
const base = dot > 0 ? name.slice(0, dot) : name;
const ext = dot > 0 ? name.slice(dot).toLowerCase() : '';

if (!name || !base) return reject('The file has no usable name.');
if (!ALLOWED.includes(ext)) return reject(`"${name}" is not a supported type. Use ${ALLOWED.join(', ')}.`);
if (/^(con|prn|aux|nul|com\d|lpt\d)$/i.test(base)) return reject('That file name is reserved by Windows.');

const bytes = (await this.helpers.getBinaryDataBuffer(0, keys[0])).length;
if (bytes === 0) return reject(`"${name}" is empty.`);
if (bytes > MAX_BYTES) return reject(`"${name}" is larger than ${MAX_BYTES / 1024 / 1024} MB.`);

const safeName = base + ext;
return [{
  json: { ok: true, safeName, path: DOCS_FOLDER + '\\' + safeName, bytes },
  binary: { data: file },
}];
